#include <stddef.h>
#include <stdint.h>
#define MAX_COUNT 64
#define MAX_TEXT 4096
static int lower_ascii(int c){return c>='A'&&c<='Z'?c+32:c;}
static int less(const int64_t*v,const size_t*o,const size_t*l,const size_t*p,size_t a,size_t b){size_t i=0,lim=p[a]<p[b]?p[a]:p[b];for(;i<lim;i++){int x=lower_ascii((int)v[o[a]+i]),y=lower_ascii((int)v[o[b]+i]);if(x!=y)return x<y;}if(p[a]!=p[b])return p[a]<p[b];size_t sa=l[a]-p[a],sb=l[b]-p[b];if(!sa||!sb)return sa<sb;size_t za=0,zb=0;while(za<sa&&v[o[a]+p[a]+za]=='0')za++;while(zb<sb&&v[o[b]+p[b]+zb]=='0')zb++;size_t na=sa-za,nb=sb-zb;if(na!=nb)return na<nb;for(i=0;i<na;i++){int x=v[o[a]+p[a]+za+i],y=v[o[b]+p[b]+zb+i];if(x!=y)return x<y;}return 0;}
int64_t natural_sort(const int64_t*v,size_t n,uint8_t*out,size_t cap){if(!v||n<1||n>4161||v[0]<0||v[0]>MAX_COUNT)return -1;size_t count=v[0],off[MAX_COUNT],len[MAX_COUNT],pre[MAX_COUNT],order[MAX_COUNT],cursor=1,total=0;for(size_t i=0;i<count;i++){if(cursor>=n||v[cursor]<0||v[cursor]>64)return -1;len[i]=v[cursor++];off[i]=cursor;pre[i]=len[i];int digit=0;for(size_t j=0;j<len[i];j++){int c=v[cursor+j];if(c>='0'&&c<='9'){if(j==0) return -1;if(!digit){pre[i]=j;digit=1;}}else if((c>='A'&&c<='Z')||(c>='a'&&c<='z')){if(digit)return -1;}else return -1;}cursor+=len[i];total+=len[i];order[i]=i;}if(cursor!=n)return -1;for(size_t i=1;i<count;i++){size_t item=order[i],j=i;while(j>0&&less(v,off,len,pre,item,order[j-1])){order[j]=order[j-1];j--;}order[j]=item;}size_t bytes=total+(count?count-1:0);if(bytes>cap||(bytes&&!out))return -2;size_t w=0;for(size_t i=0;i<count;i++){if(i)out[w++]='\n';size_t k=order[i];for(size_t j=0;j<len[k];j++)out[w++]=(uint8_t)v[off[k]+j];}return (int64_t)w;}
